<script setup lang="ts">
/**
 * Picks one node of a hierarchy, in a field (`design/components/tree-select.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree-select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/popover'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, useDirection, useMediaQuery } from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/tree-select.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Tree, { type TreeItem, type TreeMessages } from '../structure/Tree.vue'

export interface TreeSelectProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * The branches open at first, while the member holds the set.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * Opens on mount. For galleries and tests; screens let the reader open it.
   */
  defaultOpen?: boolean
  /**
   * The node chosen at first, while the member holds the choice.
   */
  defaultValue?: string
  disabled?: boolean
  /**
   * Labels a selectable empty choice, drawn as the first top-level item. Choosing it reports
   * `null`, and the trigger shows this label as a value.
   */
  emptyOption?: string
  /**
   * The open branches by id. Controlled when given; without it the member holds the set.
   */
  expanded?: ReadonlySet<string>
  /**
   * The top level has more items than `items` holds: a last row asks for them.
   */
  hasMore?: boolean
  id?: string
  invalid?: boolean
  /**
   * Tree's items: the top level, each branch holding the level under it.
   */
  items: TreeItem[]
  /**
   * Names the tree in the popup, as Tree's `label` does: "Organization units". FormField names
   * the field.
   */
  label: string
  /**
   * The top level is loading, as an item's `loading` says of its own level.
   */
  loading?: boolean
  /**
   * Tree's strings, passed to the tree in the popup. Omit for Tree's English defaults.
   */
  messages?: TreeMessages
  /**
   * A hidden field that submits the chosen id, or the empty string for none and the empty
   * choice.
   */
  name?: string
  /**
   * Muted, and shown while no node is chosen. Cannot be combined with `emptyOption`.
   */
  placeholder?: string
  /**
   * `'auto'` shows the popup as a sheet below `30rem`, as Select's. `'popover'` keeps the
   * anchored popup at every width.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * The chosen node's id. Controlled when given. `null` is no node, and the empty choice when
   * `emptyOption` is set.
   */
  value?: string | null
  /**
   * What the trigger shows while the chosen node is not in `items`, because its level is not
   * loaded. A node in `items` is shown by its own label.
   */
  valueLabel?: string
}

defineOptions({ name: 'TreeSelect', inheritAttrs: false })

const props = withDefaults(defineProps<TreeSelectProps>(), {
  ariaRequired: undefined,
  defaultOpen: undefined,
  disabled: false,
  hasMore: false,
  invalid: false,
  loading: false,
  presentation: 'auto',
  size: 'md',
})
const emit = defineEmits<{
  change: [id: string | null]
  expandedChange: [next: ReadonlySet<string>]
  loadMore: [parentId: string | null]
}>()
const uid = useId()
const ownValue = ref((props.defaultValue ?? null) as string | null)
const ownExpanded = ref(
  props.defaultOpen === true
    ? ((
        tops: TreeItem[],
        held: ReadonlySet<string>,
        target: string | null,
      ): ReadonlySet<string> => {
        const walk = (level: TreeItem[], trail: string[]): string[] | null => {
          for (const node of level) {
            if (node.id === target) return trail
            const under =
              node.children === undefined ? null : walk(node.children, [...trail, node.id])
            if (under !== null) return under
          }
          return null
        }
        const above = target === null ? null : walk(tops, [])
        return above === null || above.every((branch) => held.has(branch))
          ? held
          : new Set([...held, ...above])
      })(props.items, props.defaultExpanded ?? new Set<string>(), props.defaultValue ?? null)
    : (props.defaultExpanded ?? new Set<string>()),
)
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const trigger = useTemplateRef<HTMLElement>('trigger')
const phone = useMediaQuery('phone')
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const chosen = computed(() => (props.value === undefined ? ownValue.value : props.value))
const branches = computed(() => props.expanded ?? ownExpanded.value)
const emptyId = computed(() => `${uid}-empty`)
const panelId = computed(() => `${uid}-panel`)
const shownItems = computed(() =>
  props.emptyOption === undefined
    ? props.items
    : [{ id: emptyId.value, label: props.emptyOption }, ...props.items],
)
const treeValue = computed(
  () => chosen.value ?? (props.emptyOption === undefined ? null : emptyId.value),
)
const labelOf = computed(() => (level: TreeItem[], wanted: string): string | undefined => {
  for (const node of level) {
    if (node.id === wanted) return node.label
    const under = node.children === undefined ? undefined : labelOf.value(node.children, wanted)
    if (under !== undefined) return under
  }
  return undefined
})
const placeholderShown = computed(() => chosen.value === null && props.emptyOption === undefined)
const shown = computed(() =>
  chosen.value === null
    ? (props.emptyOption ?? props.placeholder ?? '')
    : (labelOf.value(props.items, chosen.value) ?? props.valueLabel ?? ''),
)
const changeExpanded = computed(() => (next: ReadonlySet<string>): void => {
  ownExpanded.value = next
  emit('expandedChange', next)
})
const opened = computed(() => (now: boolean): void => {
  if (!now) return
  const next = ((
    tops: TreeItem[],
    held: ReadonlySet<string>,
    target: string | null,
  ): ReadonlySet<string> => {
    const walk = (level: TreeItem[], trail: string[]): string[] | null => {
      for (const node of level) {
        if (node.id === target) return trail
        const under = node.children === undefined ? null : walk(node.children, [...trail, node.id])
        if (under !== null) return under
      }
      return null
    }
    const above = target === null ? null : walk(tops, [])
    return above === null || above.every((branch) => held.has(branch))
      ? held
      : new Set([...held, ...above])
  })(props.items, branches.value, chosen.value)
  if (next !== branches.value) changeExpanded.value(next)
})
const documentDirection = useDirection(() => trigger.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    defaultOpen: props.defaultOpen === true && !props.disabled,
    modal: true,
    positioning: { placement: 'bottom-start' as const, offset: { mainAxis: 2 } },
    ids: { ...(props.id === undefined ? {} : { trigger: props.id }), content: `${uid}-panel` },
    initialFocusEl: () => {
      const box = sheetPanel.value ?? panel.value
      return (
        box?.querySelector<HTMLElement>(
          '[role="treeitem"][aria-selected="true"]:not([aria-disabled="true"])',
        ) ??
        box?.querySelector<HTMLElement>('[role="treeitem"]:not([aria-disabled="true"])') ??
        null
      )
    },
    onOpenChange: (details) => {
      opened.value(details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const choose = computed(() => (picked: string): void => {
  const reported = picked === emptyId.value ? null : picked
  ownValue.value = reported
  emit('change', reported)
  api.value.setOpen(false)
})
const openFromKeys = computed(() => (event: KeyboardEvent): void => {
  if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return
  event.preventDefault()
  if (!props.disabled) api.value.setOpen(true)
})
const closeOnRepick = computed(() => (event: Event): void => {
  const target = event.target instanceof Element ? event.target : null
  if (target === null) return
  if (event instanceof KeyboardEvent) {
    if (
      (event.key !== 'Enter' && event.key !== ' ') ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey
    )
      return
    if (target.closest('[role="treeitem"]')?.getAttribute('aria-selected') === 'true')
      api.value.setOpen(false)
    return
  }
  if (target.closest('[data-tree-part="toggle"]') !== null) return
  if (
    target.closest('[data-tree-part="row"]')?.parentElement?.getAttribute('aria-selected') ===
    'true'
  )
    api.value.setOpen(false)
})
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'TreeSelect',
    element: () => trigger.value,
    state: () => ({
      value: chosen.value === null ? (props.emptyOption === undefined ? null : '') : chosen.value,
      options: [
        ...(props.emptyOption === undefined ? [] : [{ id: '', label: props.emptyOption }]),
        ...((
          level: TreeItem[],
        ): (Pick<TreeItem, 'id' | 'label'> & Partial<Record<'disabled', true>>)[] => {
          const out: (Pick<TreeItem, 'id' | 'label'> & Partial<Record<'disabled', true>>)[] = []
          const walk = (nodes: TreeItem[], off: boolean): void => {
            for (const node of nodes) {
              const shut = off || node.disabled === true
              out.push({
                id: node.id,
                label: node.label,
                ...(shut ? { disabled: true as const } : {}),
              })
              if (node.children !== undefined) walk(node.children, shut)
            }
          }
          walk(level, false)
          return out
        })(props.items),
      ],
      open: api.value.open,
      disabled: props.disabled,
      invalid: props.invalid,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          (value === '' ? null : value) === chosen.value ||
          choose.value(value === '' ? emptyId.value : value),
      },
      open: () => api.value.setOpen(true),
      close: () => api.value.setOpen(false),
    },
    withholds: () => sheetPanel.value ?? panel.value,
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <button
    ref="trigger"
    v-bind="api.getTriggerProps()"
    :class="styles.trigger"
    role="combobox"
    aria-haspopup="tree"
    :aria-controls="api.open ? panelId : undefined"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-required="ariaRequired"
    :aria-invalid="invalid ? true : undefined"
    :disabled="disabled ? true : undefined"
    :data-size="size"
    :data-invalid="invalid ? '' : undefined"
    :data-disabled="disabled ? '' : undefined"
    :data-placeholder="placeholderShown ? '' : undefined"
    data-member="tree-select"
    @keydown="openFromKeys($event)"
  >
    <span :class="styles.value">
      {{ shown }}
    </span>
    <span :class="styles.chevron" aria-hidden="true">
      <Icon name="expand" :size="size" />
    </span>
  </button>
  <input
    v-if="name !== undefined"
    type="hidden"
    :name="name"
    :value="chosen ?? ''"
    :disabled="disabled ? true : undefined"
  />
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.content"
        :style="{
          '--radix-popover-trigger-width': 'var(--reference-width)',
          '--radix-popover-content-available-width': 'var(--available-width)',
          '--radix-popover-content-available-height': 'var(--available-height)',
          '--radix-popover-content-transform-origin': 'var(--transform-origin)',
        }"
        :hidden="undefined"
        :role="undefined"
        :aria-modal="undefined"
        :aria-labelledby="undefined"
        :aria-describedby="undefined"
        :data-size="size"
        data-member="tree-select"
        @keydown="closeOnRepick($event)"
        @click="closeOnRepick($event)"
      >
        <Tree
          :label="label"
          :items="shownItems"
          :expanded="branches"
          :value="treeValue"
          :loading="loading"
          :hasMore="hasMore"
          :messages="messages"
          @change="choose($event)"
          @expandedChange="changeExpanded($event)"
          @loadMore="emit('loadMore', $event)"
        />
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        v-bind="api.getContentProps()"
        :class="sheet.panel"
        :hidden="undefined"
        :role="undefined"
        :aria-modal="undefined"
        :aria-labelledby="undefined"
        :aria-describedby="undefined"
        data-presentation="sheet"
      >
        <!-- sheetBody -->
        <div
          :class="styles.sheetBody"
          :data-size="size"
          data-member="tree-select"
          @keydown="closeOnRepick($event)"
          @click="closeOnRepick($event)"
        >
          <Tree
            :label="label"
            :items="shownItems"
            :expanded="branches"
            :value="treeValue"
            :loading="loading"
            :hasMore="hasMore"
            :messages="messages"
            @change="choose($event)"
            @expandedChange="changeExpanded($event)"
            @loadMore="emit('loadMore', $event)"
          />
        </div>
      </div>
    </div>
  </Teleport>
</template>
